  async def pay(self, login: str, coppers: int, label: str) -> int:
    """Pay coppers from the server account to a player, returns the BillId. This method takes three parameters:
    Login of the payee, Coppers to pay and a Label to send with the payment. The creation of the transaction
    itself may cost coppers, so you need to have coppers on the server account. Only available to Admin."""
    return await self.call('Pay', login, coppers, label)
  #

  async def send_bill(self, login_from: str, coppers: int, label: str, login_to: str) -> int:
    """Create a bill, send it to a player, and return the BillId. This method takes four parameters: LoginFrom of
    the payer, Coppers the player has to pay, Label of the transaction and an optional LoginTo of the payee
    (if empty string, then the server account is used). The creation of the transaction itself may cost
    coppers, so you need to have coppers on the server account. Only available to Admin."""
    return await self.call('SendBill', login_from, coppers, label, login_to)
  #

