  async def get_player_list(self, count: int, start: int, version: int = 1) -> list[PlayerInfo]:
    """Returns the list of players on the server. This method take two parameters. The first parameter specifies
    the maximum number of infos to be returned, and the second one the starting index in the list, an optional
    3rd parameter is used for compatibility: struct version (0 = united, 1 = forever, 2 = forever, including
    the servers). The list is an array of PlayerInfo structures. Forever PlayerInfo struct is: Login,
    NickName, PlayerId, TeamId, SpectatorStatus, LadderRanking, and Flags. LadderRanking is 0 when not in
    official mode, Flags = ForceSpectator(0,1,2) + IsReferee * 10 + IsPodiumReady * 100 + IsUsingStereoscopy *
    1000 + IsManagedByAnOtherServer * 10000 + IsServer * 100000 + HasPlayerSlot * 1000000 SpectatorStatus =
    Spectator + TemporarySpectator * 10 + PureSpectator * 100 + AutoTarget * 1000 + CurrentTargetId * 10000"""
    return await self.call('GetPlayerList', count, start, version)
  #

  async def get_player_info(self, login: str, version: int = 1) -> PlayerInfo:
    """Returns a struct containing the infos on the player with the specified login, with an optional parameter
    for compatibility: struct version (0 = united, 1 = forever). The structure is identical to the ones from
    GetPlayerList. Forever PlayerInfo struct is: Login, NickName, PlayerId, TeamId, SpectatorStatus,
    LadderRanking, and Flags. LadderRanking is 0 when not in official mode, Flags = ForceSpectator(0,1,2) +
    IsReferee * 10 + IsPodiumReady * 100 + IsUsingStereoscopy * 1000 + IsManagedByAnOtherServer * 10000 +
    IsServer * 100000 + HasPlayerSlot * 1000000 SpectatorStatus = Spectator + TemporarySpectator * 10 +
    PureSpectator * 100 + AutoTarget * 1000 + CurrentTargetId * 10000"""
    return await self.call('GetPlayerInfo', login, version)
  #

  async def get_detailed_player_info(self, login: str) -> dict:
    """Returns a struct containing the infos on the player with the specified login. The structure contains the
    following fields : Login, NickName, PlayerId, TeamId, IPAddress, DownloadRate, UploadRate, Language,
    IsSpectator, IsInOfficialMode, a structure named Avatar, an array of structures named Skins, a structure
    named LadderStats, HoursSinceZoneInscription and OnlineRights (0: nations account, 3: united account).
    Each structure of the array Skins contains two fields Environnement and a struct PackDesc. Each structure
    PackDesc, as well as the struct Avatar, contains two fields FileName and Checksum."""
    return await self.call('GetDetailedPlayerInfo', login)
  #

  async def get_main_server_player_info(self, version: int = 1) -> dict:
    """Returns a struct containing the player infos of the game server (ie: in case of a basic server, itself; in
    case of a relay server, the main server), with an optional parameter for compatibility: struct version (0
    = united, 1 = forever). The structure is identical to the ones from GetPlayerList. Forever PlayerInfo
    struct is: Login, NickName, PlayerId, TeamId, SpectatorStatus, LadderRanking, and Flags. LadderRanking is
    0 when not in official mode, Flags = ForceSpectator(0,1,2) + IsReferee * 10 + IsPodiumReady * 100 +
    IsUsingStereoscopy * 1000 + IsManagedByAnOtherServer * 10000 + IsServer * 100000 + HasPlayerSlot * 1000000
    SpectatorStatus = Spectator + TemporarySpectator * 10 + PureSpectator * 100 + AutoTarget * 1000 +
    CurrentTargetId * 10000"""
    return await self.call('GetMainServerPlayerInfo', version)
  #

  async def get_current_ranking(self, count: int, start: int) -> list[PlayerRanking]:
    """Returns the current rankings for the race in progress. (in team mode, the scores for the two teams are
    returned. In other modes, it's the individual players' scores) This method take two parameters. The first
    parameter specifies the maximum number of infos to be returned, and the second one the starting index in
    the ranking. The ranking returned is a list of structures. Each structure contains the following fields :
    Login, NickName, PlayerId, Rank, BestTime, Score, NbrLapsFinished and LadderScore. It also contains an
    array BestCheckpoints that contains the checkpoint times for the best race."""
    return await self.call('GetCurrentRanking', count, start)
  #

  async def get_current_ranking_for_login(self, login: str) -> list[PlayerRanking]:
    """Returns the current ranking for the race in progressof the player with the specified login (or list of
    comma-separated logins). The ranking returned is a list of structures, that contains the following fields
    : Login, NickName, PlayerId, Rank, BestTime, Score, NbrLapsFinished and LadderScore. It also contains an
    array BestCheckpoints that contains the checkpoint times for the best race."""
    return await self.call('GetCurrentRankingForLogin', login)
  #

  async def force_scores(self, scores: list, silent: bool) -> bool:
    """Force the scores of the current game. Only available in rounds and team mode. You have to pass an array of
    structs {int PlayerId, int Score}. And a boolean SilentMode - if true, the scores are silently updated
    (only available for SuperAdmin), allowing an external controller to do its custom counting... Only
    available to Admin/SuperAdmin."""
    return await self.call('ForceScores', scores, silent)
  #

